import {expect,test,type Page} from '@playwright/test';
async function openLesson70(page:Page){await page.goto('/');const chapterThree=page.locator('.course-chapter-group').nth(2);if(!(await chapterThree.evaluate(element=>(element as HTMLDetailsElement).open)))await chapterThree.locator('summary').click();const lessons=page.locator('.course-lesson-grid > button');await expect(lessons.nth(69)).toContainText('Деление с остатком: итоговое обобщение');await expect(lessons.nth(69)).toBeEnabled();await expect(lessons.nth(70)).toContainText('Степень числа');await page.getByRole('button',{name:/Открыть урок 70:/}).click();await page.locator('.lesson-opening-start').click()}
async function jump(page:Page,stageIndex:number){await page.evaluate(stageIndex=>window.dispatchEvent(new CustomEvent('mathnikita-go-to-stage',{detail:{lessonNumber:70,stageIndex}})),stageIndex)}
async function noHorizontalOverflow(page:Page){return page.evaluate(()=>document.documentElement.scrollWidth<=document.documentElement.clientWidth+2)}
test('lesson 70 is usable on iPad, persists retry state and reaches 50-response practice',async({page})=>{test.setTimeout(90_000);await page.addInitScript(()=>localStorage.setItem('mathnikita-mentor-auto-guide','false'));await openLesson70(page);const stage=page.locator('.lesson-runtime:not([hidden]) .interactive-stage[data-stage-id]');await expect(stage).toHaveAttribute('data-stage-id','l70-mission');expect(await noHorizontalOverflow(page)).toBeTruthy();await jump(page,6);await expect(stage).toHaveAttribute('data-stage-id','l70-531-product');const input=stage.locator('.inline-answer input');for(const wrong of ['85','83']){await input.fill(wrong);await stage.locator('.check-button').click();await expect(stage.locator('.instant-feedback.bad')).toBeVisible()}await expect(stage.locator('.lesson-controls .primary')).toBeEnabled();await input.fill('84');await stage.locator('.check-button').click();await expect(stage.locator('.instant-feedback.good')).toBeVisible();const beforeReload=await page.evaluate(()=>JSON.parse(localStorage.getItem('mathnikita-lesson-70-progress-v1')??'null'));expect(beforeReload?.results?.['l70-p3']).toBe(true);await page.reload();await page.getByRole('button',{name:/Открыть урок 70:/}).click();await page.locator('.lesson-opening-start').click();await expect(page.locator('.lesson-runtime:not([hidden]) .interactive-stage')).toHaveAttribute('data-stage-id','l70-531-product');await jump(page,35);await expect(page.locator('.lesson-runtime:not([hidden]) .interactive-stage')).toHaveAttribute('data-stage-id','l70-summary');await expect(page.locator('.extended-practice')).toHaveAttribute('data-practice-response-count','50');await expect(page.locator('.practice-pythagoras-actions button')).toHaveCount(4);expect(await noHorizontalOverflow(page)).toBeTruthy()});
